function GuestFeedGate({ locale, isSearching = false }: { locale: string; isSearching?: boolean }) {
  const copy = copyByLocale[locale === 'ar' ? 'ar' : 'en']
  const [returnUrl, setReturnUrl] = useState(`${publicBaseUrl}/${locale}`)

  useEffect(() => {
    setReturnUrl(window.location.href)
  }, [])

  const encodedReturnUrl = encodeURIComponent(returnUrl)

  return (
    <section className="overflow-hidden rounded-lg border border-[#CFE0F4] bg-white px-6 py-7 text-center sm:px-8 sm:py-8">
      <div className="mx-auto flex h-11 w-11 items-center justify-center rounded-full bg-[#EAF3FF] text-[#2378E8]">
        <IconLock aria-hidden className="h-5 w-5" stroke={1.8} />
      </div>
      <h2 className="mt-4 text-[19px] font-bold tracking-[-0.02em] text-[#101724]">
        {copy.loginTitle}
      </h2>
      <p className="mx-auto mt-2 max-w-md text-[13px] leading-6 text-[#64748B]">
        {isSearching ? copy.searchLoginDescription : copy.loginDescription}
      </p>
      <div className="mx-auto mt-5 flex max-w-sm flex-col gap-2.5 sm:flex-row sm:justify-center">
        <Link
          href={`${dashboardUrl}/auth/login?returnUrl=${encodedReturnUrl}`}
          className="inline-flex min-h-10 items-center justify-center rounded-md bg-[#2378E8] px-5 text-[13px] font-semibold text-white transition-colors hover:bg-[#1B64C5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
        >
          {copy.login}
        </Link>
        <Link
          href={`${dashboardUrl}/auth/sign-up?returnUrl=${encodedReturnUrl}`}
          className="inline-flex min-h-10 items-center justify-center rounded-md border border-[#B8CBE2] px-5 text-[13px] font-semibold text-[#36506F] transition-colors hover:bg-[#F5F8FC] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
        >
          {copy.signup}
        </Link>
      </div>
    </section>
  )
}

function FeedSearchHeader({
  locale,
  keyword,
  industry,
  contentType,
}: Required<Pick<CommunityFeedTimelineProps, 'locale' | 'keyword'>> &
  Pick<CommunityFeedTimelineProps, 'industry' | 'contentType'>) {
  const isRTL = locale === 'ar'
  const copy = copyByLocale[isRTL ? 'ar' : 'en']
  const router = useRouter()
  const { industries, isLoading } = useAllIndustries({ locale, topSubIndustry: 0 })

  const updateFilters = (nextIndustry: number | null, nextContentType: 'post' | 'article' | null) => {
    const params = new URLSearchParams({ keyword })
    if (nextIndustry) params.set('industry', String(nextIndustry))
    if (nextContentType) params.set('content_type', nextContentType)
    router.replace(`/${locale}?${params.toString()}`, { scroll: false })
  }

  return (
    <section className="overflow-hidden rounded-lg border border-[#D7E1EE] bg-white shadow-[0_8px_24px_rgba(15,23,42,0.04)]">
      <div className="flex flex-col gap-4 px-5 py-5 sm:px-6">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <span className="inline-flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-[0.12em] text-[#2378E8]">
              <IconSearch aria-hidden className="h-3.5 w-3.5" stroke={2.2} />
              {copy.searchResults}
            </span>
            <h1 className="mt-1.5 text-[20px] font-bold tracking-[-0.025em] text-[#101724] sm:text-[22px]">
              {copy.searchFor}{' '}
              <bdi className="text-[#2378E8]">“{keyword}”</bdi>
            </h1>
          </div>
          <Link
            href={`/${locale}`}
            aria-label={copy.clearSearch}
            className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[#D7E1EE] text-[#64748B] transition-colors hover:border-[#B8CBE2] hover:bg-[#F5F8FC] hover:text-[#101724] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
          >
            <IconX aria-hidden className="h-4 w-4" stroke={2} />
          </Link>
        </div>

        <div className="grid gap-2.5 border-t border-[#EDF1F6] pt-4 sm:grid-cols-[auto_minmax(0,1fr)_minmax(0,1fr)] sm:items-center">
          <span className="inline-flex items-center gap-1.5 text-[12px] font-semibold text-[#64748B]">
            <IconAdjustmentsHorizontal aria-hidden className="h-4 w-4" stroke={1.8} />
            {copy.filters}
          </span>
          <select
            value={industry ?? ''}
            disabled={isLoading}
            onChange={(event) => updateFilters(event.target.value ? Number(event.target.value) : null, contentType ?? null)}
            aria-label={copy.allIndustries}
            className="min-h-10 w-full rounded-md border border-[#D7E1EE] bg-[#F8FAFC] px-3 text-[13px] font-medium text-[#334155] outline-none transition-colors focus:border-[#2378E8] focus:ring-2 focus:ring-[#2378E8]/15 disabled:cursor-wait disabled:opacity-60"
          >
            <option value="">{copy.allIndustries}</option>
            {industries.map((item) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <select
            value={contentType ?? ''}
            onChange={(event) => updateFilters(industry ?? null, (event.target.value || null) as 'post' | 'article' | null)}
            aria-label={copy.allContent}
            className="min-h-10 w-full rounded-md border border-[#D7E1EE] bg-[#F8FAFC] px-3 text-[13px] font-medium text-[#334155] outline-none transition-colors focus:border-[#2378E8] focus:ring-2 focus:ring-[#2378E8]/15"
          >
            <option value="">{copy.allContent}</option>
            <option value="post">{copy.posts}</option>
            <option value="article">{copy.articles}</option>
          </select>
        </div>
      </div>
    </section>
  )
}

function SearchInsights({
  insights,
  locale,
}: {
  insights: CommunityFeedSearchInsight[]
  locale: string
}) {
  if (insights.length === 0) return null

  const isRTL = locale === 'ar'
  const copy = copyByLocale[isRTL ? 'ar' : 'en']

  return (
    <section className="rounded-lg border border-[#D7E1EE] bg-white p-5 sm:p-6" aria-labelledby="feed-search-insights-title">
      <div className="flex items-center gap-3">
        <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#EAF3FF] text-[#2378E8]">
          <IconBulb aria-hidden className="h-5 w-5" stroke={1.8} />
        </span>
        <div>
          <h2 id="feed-search-insights-title" className="text-[15px] font-bold text-[#101724]">
            {copy.topInsights}
          </h2>
          <p className="mt-0.5 text-[11px] text-[#7A8AA2]">{copy.topInsightsDescription}</p>
        </div>
      </div>

      <div className="mt-4 grid gap-3 sm:grid-cols-2">
        {insights.slice(0, 5).map((insight) => {
          const href = insight.url.startsWith('/') ? `/${locale}${insight.url}` : insight.url
          const itemIsRTL = insight.language === 'arabic'
          const labels = insightTypeLabels[insight.type.toLowerCase()]
          const typeLabel = labels ? labels[isRTL ? 'ar' : 'en'] : insight.type

          return (
            <Link
              key={`${insight.type}-${insight.searchable_id}`}
              href={href}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={`${copy.openInsight}: ${insight.title}`}
              className="group flex min-h-[132px] flex-col rounded-lg border border-[#E2E8F0] bg-[#FBFCFE] p-4 transition-all hover:-translate-y-0.5 hover:border-[#B8D5F8] hover:bg-white hover:shadow-[0_10px_24px_rgba(35,120,232,0.08)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
            >
              <div className="flex items-center justify-between gap-3">
                <span className="rounded-full bg-[#EAF3FF] px-2.5 py-1 text-[9px] font-bold uppercase tracking-[0.08em] text-[#2378E8]">
                  {typeLabel}
                </span>
                <IconArrowUpRight
                  aria-hidden
                  className={`h-4 w-4 shrink-0 text-[#A0AEC0] transition-all group-hover:text-[#2378E8] ${isRTL ? '-scale-x-100' : ''}`}
                  stroke={1.8}
                />
              </div>
              <h3
                dir={itemIsRTL ? 'rtl' : 'ltr'}
                className={`mt-3 line-clamp-2 text-[13px] font-bold leading-[1.55] text-[#1E293B] group-hover:text-[#185FAF] ${itemIsRTL ? 'text-right' : 'text-left'}`}
              >
                {insight.title}
              </h3>
              {insight.insighter?.name && (
                <p className={`mt-auto pt-3 text-[10px] font-medium text-[#7A8AA2] ${itemIsRTL ? 'text-right' : 'text-left'}`}>
                  {insight.insighter.name}
                </p>
              )}
            </Link>
          )
        })}
      </div>
    </section>
  )
}

export default function CommunityFeedTimeline({
  locale,
  keyword = '',
  industry = null,
  contentType = null,
}: CommunityFeedTimelineProps) {
  const copy = copyByLocale[locale === 'ar' ? 'ar' : 'en']
  const toast = useToast()
  const { user, isAuthResolved } = useUserProfile()
  const isAuthenticated = user !== null
  const normalizedKeyword = keyword.trim()
  const isSearching = normalizedKeyword.length > 0
  const [items, setItems] = useState<FeedItem[]>([])
  const [insights, setInsights] = useState<CommunityFeedSearchInsight[]>([])
  const [meta, setMeta] = useState<FeedMeta | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [isLoadingMore, setIsLoadingMore] = useState(false)
  const [loadError, setLoadError] = useState(false)
  const loadingMoreRef = useRef(false)
  const sentinelRef = useRef<HTMLDivElement | null>(null)

  const loadFirstPage = useCallback(
    async (signal?: AbortSignal) => {
      setIsLoading(true)
      setLoadError(false)
      setItems([])
      setInsights([])
      setMeta(null)

      if (isSearching && !isAuthenticated) {
        setIsLoading(false)
        return
      }

      try {
        if (isSearching) {
          const result = await searchCommunityFeed(
            locale,
            {
              keyword: normalizedKeyword,
              industry,
              contentType,
              limit: 10,
            },
            signal,
          )
          setItems(result.feed)
          setInsights(result.insights.slice(0, 5))
          setMeta(result.meta)
        } else {
          const result = isAuthenticated
            ? await getCommunityFeed(locale, null, signal)
            : await getCommunityFeedPreview(locale, signal)

          setItems(result.data)
          setMeta(result.meta)
        }
      } catch (error) {
        if (error instanceof DOMException && error.name === 'AbortError') return
        setLoadError(true)
      } finally {
        if (!signal?.aborted) setIsLoading(false)
      }
    },
    [contentType, industry, isAuthenticated, isSearching, locale, normalizedKeyword],
  )

  useEffect(() => {
    if (!isAuthResolved) return

    const controller = new AbortController()
    void loadFirstPage(controller.signal)
    return () => controller.abort()
  }, [isAuthResolved, loadFirstPage])

  useEffect(() => {
    if (!isAuthenticated) return

    const refresh = () => void loadFirstPage()
    window.addEventListener('feed:published', refresh)
    return () => window.removeEventListener('feed:published', refresh)
  }, [isAuthenticated, loadFirstPage])

  const loadMore = useCallback(async () => {
    if (
      !isAuthenticated ||
      loadingMoreRef.current ||
      !meta?.has_more ||
      !meta.next_cursor
    ) {
      return
    }

    loadingMoreRef.current = true
    setIsLoadingMore(true)

    try {
      const nextItems = isSearching
        ? (
            await searchCommunityFeed(locale, {
              keyword: normalizedKeyword,
              cursor: meta.next_cursor,
              industry,
              contentType,
              limit: 10,
            })
          )
        : await getCommunityFeed(locale, meta.next_cursor)

      const incomingItems = 'feed' in nextItems ? nextItems.feed : nextItems.data
      setItems((previous) => {
        const existingUuids = new Set(previous.map((item) => item.uuid))
        return [...previous, ...incomingItems.filter((item) => !existingUuids.has(item.uuid))]
      })
      setMeta(nextItems.meta)
    } catch (error) {
      if (error instanceof CommunityFeedApiError && error.refreshRequired) {
        toast.info(isSearching ? copy.searchSessionRefreshed : copy.sessionRefreshed, '')
        await loadFirstPage()
      } else {
        toast.error(error instanceof Error ? error.message : copy.loadError)
      }
    } finally {
      loadingMoreRef.current = false
      setIsLoadingMore(false)
    }
  }, [contentType, copy.loadError, copy.searchSessionRefreshed, copy.sessionRefreshed, industry, isAuthenticated, isSearching, loadFirstPage, locale, meta, normalizedKeyword, toast])

  useEffect(() => {
    const sentinel = sentinelRef.current
    if (!sentinel || !isAuthenticated || !meta?.has_more) return

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) void loadMore()
      },
      { rootMargin: '600px 0px' },
    )

    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [isAuthenticated, loadMore, meta?.has_more])

  const searchHeader = isSearching ? (
    <FeedSearchHeader
      locale={locale}
      keyword={normalizedKeyword}
      industry={industry}
      contentType={contentType}
    />
  ) : null

  if (!isAuthResolved || isLoading) {
    return (
      <div className="space-y-4">
        {searchHeader}
        <section aria-label={copy.loading}>
          <FeedSkeleton />
        </section>
      </div>
    )
  }

  if (isSearching && !isAuthenticated) {
    return (
      <div className="space-y-4">
        {searchHeader}
        <GuestFeedGate locale={locale} isSearching />
      </div>
    )
  }

  if (loadError) {
    return (
      <div className="space-y-4">
        {searchHeader}
        <section className="rounded-lg border border-[#DCE4EF] bg-white px-6 py-12 text-center">
          <h1 className="text-[18px] font-bold text-[#101724]">{copy.loadError}</h1>
          <button
            type="button"
            onClick={() => void loadFirstPage()}
            className="mt-4 min-h-10 rounded-md bg-[#2378E8] px-5 text-[13px] font-semibold text-white transition-colors hover:bg-[#1B64C5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2378E8] focus-visible:ring-offset-2"
          >
            {copy.tryAgain}
          </button>
        </section>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {searchHeader}
      {isSearching && <SearchInsights insights={insights} locale={locale} />}

      <section aria-label={isSearching ? copy.searchResults : copy.title}>
        {isSearching && (
          <div className="mb-3 flex items-center gap-2 px-1">
            <span className="h-1.5 w-1.5 rounded-full bg-[#2378E8]" />
            <h2 className="text-[13px] font-bold text-[#334155]">{copy.feedMatches}</h2>
          </div>
        )}

        {items.length === 0 ? (
          <div className="rounded-lg border border-[#DCE4EF] bg-white px-6 py-14 text-center">
            <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-[#EDF4FD] text-[#2378E8]">
              {isSearching ? (
                <IconSearch aria-hidden className="h-5 w-5" stroke={1.7} />
              ) : (
                <IconPhoto aria-hidden className="h-5 w-5" stroke={1.7} />
              )}
            </div>
            <h2 className="mt-4 text-[18px] font-bold text-[#101724]">
              {isSearching ? copy.noMatchesTitle : copy.emptyTitle}
            </h2>
            <p className="mx-auto mt-2 max-w-sm text-[13px] leading-6 text-[#64748B]">
              {isSearching ? copy.noMatchesDescription : copy.emptyDescription}
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {items.map((item) => (
              <FeedCard
                key={item.uuid}
                item={item}
                locale={locale}
                articleAccess="community"
              />
            ))}
          </div>
        )}

        {!isAuthenticated && !isSearching && (
          <div className="mt-4">
            <GuestFeedGate locale={locale} />
          </div>
        )}

        {isAuthenticated && meta?.has_more && (
          <div ref={sentinelRef} className="flex min-h-20 items-center justify-center" aria-live="polite">
            {isLoadingMore && (
              <span className="inline-flex items-center gap-2 text-[13px] text-[#64748B]">
                <IconLoader2 aria-hidden className="h-4 w-4 animate-spin" stroke={2} />
                {copy.loadingMore}
              </span>
            )}
          </div>
        )}

        {isAuthenticated && items.length > 0 && meta && !meta.has_more && (
          <p className="py-6 text-center text-[12px] text-[#8A99B1]">
            {isSearching ? copy.noMoreMatches : copy.endOfFeed}
          </p>
        )}
      </section>
    </div>
  )
}
